-- PREPARED ONLY. Never apply without a new environment-specific authorization.
-- UTC filename generated by CLI; preparation authorized 19/11/2026 America/Lima.
-- 2C.2: query paths are pure; accepted historical responses never grant authority.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table private.barbershop_ownership (
 barbershop_id uuid primary key references public.barbershops(id) on delete restrict,
 owner_user_id uuid not null,
 created_by uuid references public.profiles(id) on delete restrict,
 version bigint not null default 1 check(version>0),
 source text not null check(source in('new-shop','reviewed-legacy')),
 established_at timestamptz not null default clock_timestamp(),
 foreign key(owner_user_id,barbershop_id) references public.barbershop_memberships(user_id,barbershop_id) on delete restrict
);
create table private.team_authority_events (
 id uuid primary key default gen_random_uuid(),
 barbershop_id uuid not null references public.barbershops(id) on delete restrict,
 actor_user_id uuid references public.profiles(id) on delete restrict,
 target_user_id uuid references public.profiles(id) on delete restrict,
 request_id uuid not null, action text not null,
 fingerprint jsonb not null,before_state jsonb not null,after_state jsonb not null,result jsonb not null,
 reason text, occurred_at timestamptz not null default clock_timestamp(),
 unique(actor_user_id,request_id)
);
create index team_authority_events_shop on private.team_authority_events(barbershop_id,occurred_at,id);
create table private.ownership_transfers (
 id uuid primary key default gen_random_uuid(),
 barbershop_id uuid not null references private.barbershop_ownership(barbershop_id) on delete restrict,
 initiated_by uuid not null references public.profiles(id) on delete restrict,
 recipient_user_id uuid not null,
 owner_version bigint not null,
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null,
 status text not null default 'pending' check(status in('pending','cancelled','rejected','expired')),
 check(initiated_by<>recipient_user_id),check(expires_at>created_at),
 foreign key(recipient_user_id,barbershop_id) references public.barbershop_memberships(user_id,barbershop_id) on delete restrict
);
create unique index ownership_transfers_one_pending on private.ownership_transfers(barbershop_id) where status='pending';
create table private.authority_invitation_stamp (
 invitation_id uuid primary key references public.staff_invitations(id) on delete restrict,
 owner_user_id uuid not null references public.profiles(id) on delete restrict,
 owner_version bigint not null check(owner_version>0)
);
alter table private.barbershop_ownership enable row level security;
alter table private.team_authority_events enable row level security;
alter table private.ownership_transfers enable row level security;
alter table private.authority_invitation_stamp enable row level security;
revoke all on private.barbershop_ownership,private.team_authority_events,private.ownership_transfers,private.authority_invitation_stamp from public,anon,authenticated,service_role;

-- Same first resource as existing booking/care/reschedule writers: shop configuration.
-- Only mutation paths call this helper. Capability reads never provision settings.
create function private.authority_lock(shop uuid) returns void
language plpgsql security definer set search_path='' as $fn$
begin
 -- Counting after a waited lock requires fresh READ COMMITTED statement snapshots.
 -- Reject an unexpected isolation level instead of accepting a stale quota snapshot.
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='DEPENDENCY_UNAVAILABLE';end if;
 if not exists(select 1 from public.barbershops where id=shop) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 insert into public.barbershop_booking_settings(barbershop_id) values(shop) on conflict do nothing;
 perform 1 from public.barbershop_booking_settings where barbershop_id=shop for update;
end;$fn$;
create function private.authority_owner(actor uuid,shop uuid) returns boolean
language sql stable security definer set search_path='' as $fn$
 select exists(select 1 from private.barbershop_ownership o join public.barbershop_memberships m
 on m.user_id=o.owner_user_id and m.barbershop_id=o.barbershop_id
 where o.barbershop_id=shop and o.owner_user_id=actor and m.role='administrator' and m.status='active');
$fn$;
create function private.authority_assert(actor uuid,shop uuid,capability text,writing boolean default true) returns void
language plpgsql security definer set search_path='' as $fn$
begin
 perform private.booking_actor(actor);
 if not exists(select 1 from private.barbershop_ownership where barbershop_id=shop) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if capability not in('team','publish','refund','administrators','transfer','services','hours','operations') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if writing then
  perform 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active' for share;
 else
  perform 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active';
 end if;
 if not found or(capability in('team','publish','refund','administrators','transfer') and not private.authority_owner(actor,shop)) then raise exception using errcode='42501',message='FORBIDDEN';end if;
end;$fn$;
create function private.authority_assert_room(shop uuid,recipient uuid) returns void
language plpgsql security definer set search_path='' as $fn$
declare secondary_count integer;
begin
 select count(*) into secondary_count from public.barbershop_memberships m join private.barbershop_ownership o on o.barbershop_id=m.barbershop_id
 where m.barbershop_id=shop and m.role='administrator' and m.status='active' and m.user_id<>o.owner_user_id and m.user_id<>recipient;
 if secondary_count>=2 then raise exception using errcode='23505',message='CONFLICT';end if;
end;$fn$;
create function private.authority_invariant() returns trigger
language plpgsql security definer set search_path='' as $fn$
declare shop uuid; o private.barbershop_ownership; secondary_count integer;
begin
 shop:=case when TG_OP='DELETE' then old.barbershop_id else new.barbershop_id end;
 perform private.authority_lock(shop);
 select * into o from private.barbershop_ownership where barbershop_id=shop;
 if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if not private.authority_owner(o.owner_user_id,shop) then raise exception using errcode='23514',message='CONFLICT';end if;
 select count(*) into secondary_count from public.barbershop_memberships where barbershop_id=shop and role='administrator' and status='active' and user_id<>o.owner_user_id;
 if secondary_count>2 then raise exception using errcode='23514',message='CONFLICT';end if;
 if TG_OP='UPDATE' then
  if old.barbershop_id<>new.barbershop_id then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if TG_TABLE_NAME='barbershop_memberships' then
   if old.user_id<>new.user_id then raise exception using errcode='42501',message='FORBIDDEN';end if;
  end if;
 end if;
 return null;
end;$fn$;
create constraint trigger authority_membership_invariant after insert or update or delete on public.barbershop_memberships deferrable initially deferred for each row execute function private.authority_invariant();
create constraint trigger authority_ownership_invariant after insert or update or delete on private.barbershop_ownership deferrable initially deferred for each row execute function private.authority_invariant();
create function private.authority_no_event_changes() returns trigger language plpgsql set search_path='' as $fn$
begin raise exception using errcode='42501',message='FORBIDDEN';end;$fn$;
create trigger authority_event_append_only before update or delete on private.team_authority_events for each row execute function private.authority_no_event_changes();

create function private.authority_current_owner(shop uuid) returns boolean language sql stable security definer set search_path='' as $fn$
 select private.authority_owner((select auth.uid()),shop);$fn$;
create function private.authority_current_operator(shop uuid) returns boolean language sql stable security definer set search_path='' as $fn$
 select exists(select 1 from private.barbershop_ownership o join public.barbershop_memberships m on m.barbershop_id=o.barbershop_id where o.barbershop_id=shop and m.user_id=(select auth.uid()) and m.role='administrator' and m.status='active');$fn$;
revoke all on function private.authority_current_operator(uuid) from public,anon,authenticated,service_role;
grant execute on function private.authority_current_operator(uuid) to authenticated;
alter policy barbershops_update_active_admin on public.barbershops using(private.authority_current_operator(id)) with check(private.authority_current_operator(id));
revoke all on function private.authority_current_owner(uuid) from public,anon,authenticated,service_role;
grant execute on function private.authority_current_owner(uuid) to authenticated;
alter policy memberships_select_own on public.barbershop_memberships using(user_id=(select auth.uid()) or private.authority_current_owner(barbershop_id));
alter policy staff_invitations_read on public.staff_invitations using(recipient_user_id=(select auth.uid()) or private.authority_current_owner(barbershop_id));
create or replace function public.list_barbershop_memberships(p_barbershop_id uuid)
returns table(id uuid,user_id uuid,barbershop_id uuid,role text,status text)
language plpgsql security invoker set search_path='' as $fn$
begin
 if not private.authority_current_owner(p_barbershop_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 return query select m.id,m.user_id,m.barbershop_id,m.role,m.status from public.barbershop_memberships m where m.barbershop_id=p_barbershop_id;
end;$fn$;
-- No direct membership writer grant is added. No old payment-confirmation grant reopened.

create function private.authority_capabilities(actor uuid,shop uuid) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare capacity text; o private.barbershop_ownership; role_name text; count_secondary integer; permitted boolean;
begin
 perform private.booking_actor(actor);
 select role into role_name from public.barbershop_memberships where user_id=actor and barbershop_id=shop and status='active';
 if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
 select * into o from private.barbershop_ownership where barbershop_id=shop;
 capacity:=case when o.barbershop_id is null then 'unregularized' when role_name='barber' then 'barber' when private.authority_owner(actor,shop) then 'owner' else 'secondary' end;
 permitted:=capacity in('owner','secondary');
 select count(*) into count_secondary from public.barbershop_memberships where barbershop_id=shop and role='administrator' and status='active' and user_id is distinct from o.owner_user_id;
 return jsonb_build_object('revision','20261120010538','userId',actor,'barbershopId',shop,'capacity',capacity,'version',coalesce(o.version,0),
 'secondaryCount',case when capacity='owner' then count_secondary else null end,
 'permissions',jsonb_build_object('manageAdministrators',capacity='owner','transferOwnership',capacity='owner','manageTeam',capacity='owner','publish',capacity='owner','refund',capacity='owner','editServices',permitted,'editHours',permitted,'manageReservations',permitted,'confirmPayment',permitted));
end;$fn$;

create function private.authority_validate_invitation(invitation uuid) returns void
language plpgsql security definer set search_path='' as $fn$
declare i public.staff_invitations; stamp private.authority_invitation_stamp;
begin
 select * into i from public.staff_invitations where id=invitation;
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 select * into stamp from private.authority_invitation_stamp where invitation_id=i.id;
 if not found or not exists(select 1 from private.barbershop_ownership where barbershop_id=i.barbershop_id and owner_user_id=stamp.owner_user_id and version=stamp.owner_version) or not private.authority_owner(i.inviter_user_id,i.barbershop_id) then raise exception using errcode='42501',message='FORBIDDEN';end if;
end;$fn$;

-- Preserve existing public create contract, add ownership in the same transaction.
create or replace function private.create_own_barbershop(p_actor_id uuid,p_name text) returns jsonb
language plpgsql security definer set search_path='' as $function$
declare shop public.barbershops; member public.barbershop_memberships;
begin
 perform private.booking_actor(p_actor_id);
 if p_name is null or btrim(p_name)='' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 insert into public.barbershops(name) values(btrim(p_name)) returning * into shop;
 insert into public.barbershop_memberships(user_id,barbershop_id,role,status) values(p_actor_id,shop.id,'administrator','active') returning * into member;
 perform private.authority_lock(shop.id);
 insert into private.barbershop_ownership(barbershop_id,owner_user_id,created_by,source) values(shop.id,p_actor_id,p_actor_id,'new-shop');
 insert into private.team_authority_events(barbershop_id,actor_user_id,target_user_id,request_id,action,fingerprint,before_state,after_state,result)
 values(shop.id,p_actor_id,p_actor_id,gen_random_uuid(),'created','{}','{}',jsonb_build_object('owner',p_actor_id),jsonb_build_object('ok',true));
 return jsonb_build_object('barbershop',to_jsonb(shop),'membership',to_jsonb(member));
end;$function$;

-- Operator-only regularization. No grant to service_role, no HTTP/Edge command.
-- A reviewed exact membership snapshot and explicit owner are mandatory; no inference.
create function private.regularize_barbershop_ownership(shop uuid,chosen_owner uuid,expected_members jsonb,reason text) returns void
language plpgsql security definer set search_path='' as $fn$
declare actual jsonb;
begin
 if reason is null or length(btrim(reason))<1 or expected_members is null then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 perform private.authority_lock(shop);
 perform private.booking_actor(chosen_owner);
 select coalesce(jsonb_agg(jsonb_build_object('userId',user_id,'role',role,'status',status) order by user_id),'[]') into actual from public.barbershop_memberships where barbershop_id=shop;
 if actual<>expected_members or exists(select 1 from private.barbershop_ownership where barbershop_id=shop) then raise exception using errcode='23505',message='CONFLICT';end if;
 if not exists(select 1 from public.barbershop_memberships where barbershop_id=shop and user_id=chosen_owner and role='administrator' and status='active') then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if(select count(*) from public.barbershop_memberships where barbershop_id=shop and role='administrator' and status='active' and user_id<>chosen_owner)>2 then raise exception using errcode='23505',message='CONFLICT';end if;
 insert into private.barbershop_ownership(barbershop_id,owner_user_id,created_by,source) values(shop,chosen_owner,null,'reviewed-legacy');
 insert into private.team_authority_events(barbershop_id,target_user_id,request_id,action,fingerprint,before_state,after_state,result,reason)
 values(shop,chosen_owner,gen_random_uuid(),'regularized',jsonb_build_object('source','reviewed-legacy'),jsonb_build_object('members',actual),jsonb_build_object('owner',chosen_owner),jsonb_build_object('ok',true),reason);
end;$fn$;

create function public.team_authority_command(p_actor_id uuid,p_action text,p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare actor uuid:=p_actor_id;shop uuid;target uuid;request uuid;epoch bigint;o private.barbershop_ownership;
 old_event private.team_authority_events; member public.barbershop_memberships; transfer private.ownership_transfers;
 result jsonb; before_value jsonb;
begin
 perform private.booking_actor(actor);
 if p_action='read-team-authority' then
  perform private.booking_keys(p_data,array['barbershopId']);return private.authority_capabilities(actor,(p_data->>'barbershopId')::uuid);
 end if;
 if p_action='accept-ownership-transfer' then
  -- TRANSFER_CONFIRMATION_NOT_APPROVED: previous owner's disposition is undecided.
  raise exception using errcode='23505',message='CONFLICT';
 elsif p_action='remove-secondary' then perform private.booking_keys(p_data,array['barbershopId','requestId','expectedVersion','memberUserId','disposition','reason']);
 elsif p_action='initiate-ownership-transfer' then perform private.booking_keys(p_data,array['barbershopId','requestId','expectedVersion','recipientUserId']);
 elsif p_action in('cancel-ownership-transfer','reject-ownership-transfer') then perform private.booking_keys(p_data,array['barbershopId','requestId','expectedVersion','transferId']);
 else raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if jsonb_typeof(p_data->'barbershopId') is distinct from 'string' or jsonb_typeof(p_data->'requestId') is distinct from 'string' or jsonb_typeof(p_data->'expectedVersion') is distinct from 'number' or(p_data->>'expectedVersion')!~'^[1-9][0-9]*$' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 shop:=(p_data->>'barbershopId')::uuid;request:=(p_data->>'requestId')::uuid;epoch:=(p_data->>'expectedVersion')::bigint;
 if shop is null or request is null or epoch is null or epoch<1 then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 perform private.authority_lock(shop);
 select * into o from private.barbershop_ownership where barbershop_id=shop;
 if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if p_action<>'reject-ownership-transfer' then perform private.authority_assert(actor,shop,'administrators');end if;
 if o.version<>epoch then raise exception using errcode='23505',message='CONFLICT';end if;
 select * into old_event from private.team_authority_events where actor_user_id=actor and request_id=request;
 if found then
  if old_event.fingerprint<>jsonb_build_object('action',p_action,'data',p_data) then raise exception using errcode='23505',message='CONFLICT';end if;
  return old_event.result;
 end if;
 if p_action='remove-secondary' then
  target:=(p_data->>'memberUserId')::uuid;
  if target=o.owner_user_id or target is null then raise exception using errcode='42501',message='FORBIDDEN';end if;
  select * into member from public.barbershop_memberships where user_id=target and barbershop_id=shop for update;
  if not found or member.role<>'administrator' or member.status<>'active' then raise exception using errcode='23505',message='CONFLICT';end if;
  if jsonb_typeof(p_data->'reason') is distinct from 'string' or jsonb_typeof(p_data->'disposition') is distinct from 'string' or length(btrim(p_data->>'reason')) not between 1 and 1000 or(p_data->>'disposition') not in('barber','inactive') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  if exists(select 1 from private.ownership_transfers where barbershop_id=shop and recipient_user_id=target and status='pending' and expires_at>clock_timestamp()) then raise exception using errcode='23505',message='CONFLICT';end if;
  if p_data->>'disposition'='barber' then
   if not exists(select 1 from public.barber_profiles where barbershop_id=shop and user_id=target and active) then raise exception using errcode='23505',message='CONFLICT';end if;
  elsif exists(select 1 from public.reservations r left join private.booking_care c on c.reservation_id=r.id where r.barbershop_id=shop and r.barber_user_id=target and r.state='confirmed' and(r.starts_at>=clock_timestamp() or c.attendance='in-service')) then raise exception using errcode='23505',message='CONFLICT';end if;
  before_value:=jsonb_build_object('role',member.role,'status',member.status);
  update public.barbershop_memberships set role='barber',status=case when p_data->>'disposition'='barber' then 'active' else 'inactive' end where id=member.id returning * into member;
  result:=jsonb_build_object('ok',true,'memberUserId',target,'role',member.role,'status',member.status,'version',o.version);
 elsif p_action='initiate-ownership-transfer' then
  target:=(p_data->>'recipientUserId')::uuid;
  if target=actor or not exists(select 1 from public.barbershop_memberships where user_id=target and barbershop_id=shop and role='administrator' and status='active') then raise exception using errcode='42501',message='FORBIDDEN';end if;
  perform private.booking_actor(target);
  update private.ownership_transfers set status='expired' where barbershop_id=shop and status='pending' and expires_at<=clock_timestamp();
  insert into private.ownership_transfers(barbershop_id,initiated_by,recipient_user_id,owner_version,expires_at) values(shop,actor,target,o.version,clock_timestamp()+interval '7 days') returning * into transfer;
  before_value:='{}';result:=jsonb_build_object('ok',true,'transferId',transfer.id,'status',transfer.status,'expiresAt',transfer.expires_at,'confirmationBlocked',true,'version',o.version);
 else
  select * into transfer from private.ownership_transfers where id=(p_data->>'transferId')::uuid and barbershop_id=shop for update;
  if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  if p_action='reject-ownership-transfer' and transfer.recipient_user_id<>actor then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if transfer.status<>'pending' or transfer.expires_at<=clock_timestamp() or transfer.owner_version<>o.version or transfer.initiated_by<>o.owner_user_id then raise exception using errcode='23505',message='CONFLICT';end if;
  target:=transfer.recipient_user_id;before_value:=jsonb_build_object('status',transfer.status);
  update private.ownership_transfers set status=case when p_action='reject-ownership-transfer' then 'rejected' else 'cancelled' end where id=transfer.id returning * into transfer;
  result:=jsonb_build_object('ok',true,'transferId',transfer.id,'status',transfer.status,'version',o.version);
 end if;
 insert into private.team_authority_events(barbershop_id,actor_user_id,target_user_id,request_id,action,fingerprint,before_state,after_state,result,reason)
 values(shop,actor,target,request,p_action,jsonb_build_object('action',p_action,'data',p_data),before_value,result,result,p_data->>'reason');
 return result;
exception when unique_violation then raise exception using errcode='23505',message='CONFLICT';
 when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='INVALID_INPUT';
end;$fn$;
revoke all on function public.team_authority_command(uuid,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.team_authority_command(uuid,text,jsonb) to service_role;
-- BEGIN GUARDED COMPATIBILITY REPLACEMENTS
create or replace function private.booking_command(actor uuid,action text,d jsonb) returns jsonb language plpgsql security definer set search_path='' as $fn$
declare shop uuid; entity uuid; recipient uuid; professional uuid; invitation public.staff_invitations; service public.services; person public.barber_profiles; item jsonb; result jsonb:='null'; selected_ids uuid[];
begin
 perform private.booking_actor(actor);
 if action in('accept-invitation','reject-invitation','cancel-invitation') then
  perform private.booking_keys(d,array['invitationId']);
  select * into invitation from public.staff_invitations where id=(d->>'invitationId')::uuid;
  if not found or (action<>'cancel-invitation' and invitation.recipient_user_id<>actor) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  shop:=invitation.barbershop_id;
  perform private.authority_lock(shop);
  if action='cancel-invitation' then perform private.authority_assert(actor,shop,'team');
  elsif action='accept-invitation' and not private.authority_owner(invitation.inviter_user_id,shop) then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if action='cancel-invitation' then perform private.booking_admin(actor,shop);
  else perform 1 from public.barbershop_booking_settings where barbershop_id=shop for update;end if;
  select * into invitation from public.staff_invitations where id=invitation.id for update;
  if invitation.status<>'pending' then raise exception using errcode='23505',message='CONFLICT';end if;
  if action='cancel-invitation' then update public.staff_invitations set status='cancelled',responded_at=statement_timestamp() where id=invitation.id returning * into invitation;
  elsif action='reject-invitation' then update public.staff_invitations set status='rejected',responded_at=statement_timestamp() where id=invitation.id returning * into invitation;
  else
   perform 1 from public.barbershop_memberships where user_id=invitation.inviter_user_id and barbershop_id=shop and role='administrator' and status='active' for share;
   if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
   if exists(select 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and status='active' and role<>'barber') then raise exception using errcode='23505',message='CONFLICT';end if;
   insert into public.barbershop_memberships(user_id,barbershop_id,role,status) values(actor,shop,'barber','active') on conflict(user_id,barbershop_id) do update set role='barber',status='active' where public.barbershop_memberships.status='inactive' or public.barbershop_memberships.role='barber';
   if not found then raise exception using errcode='23505',message='CONFLICT';end if;
   update public.staff_invitations set status='accepted',responded_at=statement_timestamp() where id=invitation.id returning * into invitation;
  end if;
  return private.booking_invitation_json(invitation);
 end if;
 shop:=(d->>'barbershopId')::uuid;
 perform private.authority_lock(shop);
 if action='set-publication' then perform private.authority_assert(actor,shop,'publish');
 elsif action in('set-professional','set-capabilities','invite-existing-user') then perform private.authority_assert(actor,shop,'team');
 elsif action in('set-hours','set-exception') then perform private.authority_assert(actor,shop,'hours');
 else perform private.authority_assert(actor,shop,'services');end if;
 perform private.booking_admin(actor,shop);
 case action
 when 'configure-shop' then
  perform private.booking_keys(d,array['barbershopId','publicContact','address','policies']);
  perform private.booking_keys(d->'policies',array['minimumNoticeMin','bookingHorizonDays','maxFuturePerClient','slotStepMin','bufferMin','cancellationAdvanceMin']);
  update public.barbershop_booking_settings set public_contact=d->>'publicContact',address=d->>'address',minimum_notice_min=(d->'policies'->>'minimumNoticeMin')::integer,booking_horizon_days=(d->'policies'->>'bookingHorizonDays')::integer,max_future_per_client=(d->'policies'->>'maxFuturePerClient')::integer,slot_step_min=(d->'policies'->>'slotStepMin')::integer,buffer_min=(d->'policies'->>'bufferMin')::integer,cancellation_advance_min=(d->'policies'->>'cancellationAdvanceMin')::integer where barbershop_id=shop;
 when 'set-publication' then
  perform private.booking_keys(d,array['barbershopId','state']);
  if d->>'state'='published' and not exists(select 1 from public.services s join public.barber_services c on c.service_id=s.id and c.barbershop_id=s.barbershop_id and c.active join public.barber_profiles p on p.id=c.barber_id and p.barbershop_id=c.barbershop_id and p.active join public.barbershop_memberships m on m.user_id=p.user_id and m.barbershop_id=p.barbershop_id and m.status='active' where s.barbershop_id=shop and s.active and exists(select 1 from public.barber_schedules h where h.barber_id=p.id and h.barbershop_id=shop)) then raise exception using errcode='23514',message='CONFLICT';end if;
  update public.barbershop_booking_settings set publication_state=d->>'state' where barbershop_id=shop;
 when 'upsert-service' then
  perform private.booking_keys(d,array['barbershopId','name','description','price','durationMin','active'],array['id']);
  perform private.booking_keys(d->'price',array['amountMinor','currency']);
  if (d->'price'->>'currency') is distinct from 'PEN' or jsonb_typeof(d->'price'->'amountMinor') is distinct from 'number' or (d->'price'->>'amountMinor')!~'^[0-9]+$' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  if d ? 'id' then update public.services set name=d->>'name',description=d->>'description',price_amount=(d->'price'->>'amountMinor')::numeric/100,duration_min=(d->>'durationMin')::integer,active=(d->>'active')::boolean where id=(d->>'id')::uuid and barbershop_id=shop returning * into service;
   if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  else insert into public.services(barbershop_id,name,description,price_amount,duration_min,active) values(shop,d->>'name',d->>'description',(d->'price'->>'amountMinor')::numeric/100,(d->>'durationMin')::integer,(d->>'active')::boolean) returning * into service;end if;
  result:=jsonb_build_object('id',service.id,'barbershopId',shop,'name',service.name,'description',service.description,'price',jsonb_build_object('amountMinor',(service.price_amount*100)::bigint,'currency','PEN'),'durationMin',service.duration_min,'active',service.active);
 when 'set-professional' then
  perform private.booking_keys(d,array['barbershopId','userId','professionalName','active'],array['id']);
  recipient:=(d->>'userId')::uuid;
  perform 1 from public.barbershop_memberships where barbershop_id=shop and user_id=recipient and status='active' for share;
  if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  if d ? 'id' then update public.barber_profiles set professional_name=d->>'professionalName',active=(d->>'active')::boolean where id=(d->>'id')::uuid and barbershop_id=shop and user_id=recipient returning * into person;
   if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  else insert into public.barber_profiles(barbershop_id,user_id,professional_name,active) values(shop,recipient,d->>'professionalName',(d->>'active')::boolean) on conflict(user_id,barbershop_id) do update set professional_name=excluded.professional_name,active=excluded.active returning * into person;end if;
  result:=jsonb_build_object('id',person.id,'barbershopId',shop,'userId',person.user_id,'professionalName',person.professional_name,'active',person.active);
 when 'set-capabilities' then
  perform private.booking_keys(d,array['barbershopId','barberId','serviceIds']);professional:=(d->>'barberId')::uuid;
  if not exists(select 1 from public.barber_profiles where id=professional and barbershop_id=shop) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  if jsonb_typeof(d->'serviceIds') is distinct from 'array' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  select coalesce(array_agg(v::uuid),array[]::uuid[]) into selected_ids from jsonb_array_elements_text(d->'serviceIds') v;
  if cardinality(selected_ids)<>(select count(distinct v) from unnest(selected_ids)v) or exists(select 1 from unnest(selected_ids)v where not exists(select 1 from public.services where id=v and barbershop_id=shop)) then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  delete from public.barber_services where barbershop_id=shop and barber_id=professional;
  insert into public.barber_services(barbershop_id,barber_id,service_id) select shop,professional,v from unnest(selected_ids)v;
 when 'set-hours' then
  perform private.booking_keys(d,array['barbershopId','hours'],array['barberId']);
  if jsonb_typeof(d->'hours') is distinct from 'array' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  professional:=(d->>'barberId')::uuid;
  if professional is not null and not exists(select 1 from public.barber_profiles where id=professional and barbershop_id=shop) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  set constraints public.shop_hours_containment,public.professional_hours_containment deferred;
  if professional is null then delete from public.barbershop_hours where barbershop_id=shop;else delete from public.barber_schedules where barbershop_id=shop and barber_id=professional;end if;
  for item in select * from jsonb_array_elements(d->'hours') loop
   perform private.booking_keys(item,array['weekday','opensMin','closesMin']);
   if professional is null then insert into public.barbershop_hours(barbershop_id,weekday,opens_min,closes_min) values(shop,(item->>'weekday')::integer,(item->>'opensMin')::integer,(item->>'closesMin')::integer);
   else insert into public.barber_schedules(barbershop_id,barber_id,weekday,opens_min,closes_min) values(shop,professional,(item->>'weekday')::integer,(item->>'opensMin')::integer,(item->>'closesMin')::integer);end if;
  end loop;
  set constraints public.shop_hours_containment,public.professional_hours_containment immediate;
 when 'set-exception' then
  perform private.booking_keys(d,array['barbershopId','barberId','startsAt','endsAt','reason']);
  insert into public.schedule_exceptions(barbershop_id,barber_id,starts_at,ends_at,reason) values(shop,(d->>'barberId')::uuid,(d->>'startsAt')::timestamptz,(d->>'endsAt')::timestamptz,d->>'reason');
 when 'invite-existing-user' then
  perform private.booking_keys(d,array['barbershopId','email']);
  select u.id into recipient from auth.users u join public.profiles p on p.id=u.id where lower(u.email)=lower(btrim(d->>'email')) and u.is_anonymous=false and u.email_confirmed_at is not null;
  if recipient is null then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  insert into public.staff_invitations(barbershop_id,recipient_user_id,inviter_user_id) values(shop,recipient,actor) returning * into invitation;
  result:=private.booking_invitation_json(invitation);
 else raise exception using errcode='22023',message='INVALID_INPUT';
 end case;
 perform private.booking_preserve_reservations(shop);
 update public.barbershop_booking_settings set version=version+1 where barbershop_id=shop;
 return result;
end;$fn$;

create or replace function private.admin_invitation_admin(actor uuid,shop uuid) returns void
language plpgsql security invoker set search_path='' as $fn$
begin
 -- Query-only authorization. Mutating callers acquire the common lock first.
 perform private.authority_assert(actor,shop,'administrators',false);
end;$fn$;

create or replace function private.admin_invitation_command(actor uuid,action text,d jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $fn$
declare i public.staff_invitations;m private.admin_invitation_mail;shop uuid;target uuid;recipient uuid;
 before_member jsonb;request uuid;stamp timestamptz;address text;claim uuid;requested_state text;
begin
 perform private.booking_actor(actor);
 if action='create' then
  perform private.booking_keys(d,array['requestId','barbershopId','email']);
  if jsonb_typeof(d->'requestId') is distinct from 'string' or jsonb_typeof(d->'barbershopId') is distinct from 'string'
   or jsonb_typeof(d->'email') is distinct from 'string' or length(d->>'email')>254
   or(d->>'email') ~ '[\r\n]' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  shop:=(d->>'barbershopId')::uuid;request:=(d->>'requestId')::uuid;address:=lower(btrim(d->>'email'));
  perform private.authority_lock(shop);
  perform private.authority_assert(actor,shop,'administrators');
  perform pg_advisory_xact_lock(hashtextextended('admin-invitation-shop:'||shop::text,0));
  stamp:=clock_timestamp();
  select * into m from private.admin_invitation_mail where requesting_actor_id=actor and request_id=request for update;
  if found then
   if m.fingerprint<>jsonb_build_object('barbershopId',shop,'email',address) then raise exception using errcode='23505',message='CONFLICT';end if;
   select * into i from public.staff_invitations where id=m.invitation_id;
   return private.admin_invitation_json(i);
  end if;
  select u.id into recipient from auth.users u join public.profiles p on p.id=u.id
    where lower(u.email)=address and u.email_confirmed_at is not null and not u.is_anonymous
      and(u.banned_until is null or u.banned_until<=stamp) for share of u;
  if not found then raise exception using errcode='P0001',message='PROFILE_REQUIRED';end if;
  if exists(select 1 from public.barbershop_memberships where user_id=recipient and barbershop_id=shop and role='administrator' and status='active') then raise exception using errcode='23505',message='CONFLICT';end if;
  -- Expire only new administrator invitations, never any existing barber invitation.
  for i in select x.* from public.staff_invitations x join private.admin_invitation_mail md on md.invitation_id=x.id
    where x.barbershop_id=shop and x.recipient_user_id=recipient and x.role='administrator' and x.status='pending' and md.expires_at<=stamp for update of x
  loop
   update public.staff_invitations set status='cancelled',responded_at=stamp where id=i.id;
   update private.admin_invitation_mail set expired=true where invitation_id=i.id;
  end loop;
  if exists(select 1 from public.staff_invitations where barbershop_id=shop and recipient_user_id=recipient and status='pending') then raise exception using errcode='23505',message='CONFLICT';end if;
  insert into public.staff_invitations(barbershop_id,recipient_user_id,inviter_user_id,role,created_at) values(shop,recipient,actor,'administrator',clock_timestamp()) returning * into i;
  insert into private.admin_invitation_mail(invitation_id,requesting_actor_id,request_id,fingerprint,recipient_email,expires_at)
    values(i.id,actor,request,jsonb_build_object('barbershopId',shop,'email',address),address,i.created_at+interval '7 days');
  insert into private.authority_invitation_stamp(invitation_id,owner_user_id,owner_version)
    select i.id,owner_user_id,version from private.barbershop_ownership where barbershop_id=shop;
  return private.admin_invitation_json(i);
 elsif action='list' then
  perform private.booking_keys(d,array['barbershopId']);
  if jsonb_typeof(d->'barbershopId')='null' then shop:=null;
  elsif jsonb_typeof(d->'barbershopId')='string' then shop:=(d->>'barbershopId')::uuid;perform private.admin_invitation_admin(actor,shop);
  else raise exception using errcode='22023',message='INVALID_INPUT';end if;
  return coalesce((select jsonb_agg(private.admin_invitation_json(x) order by x.created_at desc,x.id desc)
   from(select inv.* from public.staff_invitations inv join private.admin_invitation_mail md on md.invitation_id=inv.id
   where inv.role='administrator' and(case when shop is null then inv.recipient_user_id=actor else inv.barbershop_id=shop end)
   order by inv.created_at desc,inv.id desc limit 200)x),'[]'::jsonb);
 end if;
 if action='respond' then perform private.booking_keys(d,array['invitationId','decision']);
 elsif action='claim' then perform private.booking_keys(d,array['invitationId','claimId']);
 elsif action='finish' then perform private.booking_keys(d,array['invitationId','claimId','status']);
 elsif action in('get','cancel') then perform private.booking_keys(d,array['invitationId']);
 else raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if jsonb_typeof(d->'invitationId') is distinct from 'string' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 target:=(d->>'invitationId')::uuid;
 select * into i from public.staff_invitations where id=target and role='administrator';
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 shop:=i.barbershop_id;
 select * into m from private.admin_invitation_mail where invitation_id=target;
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 -- HISTORICAL RESPONSE ONLY: identity and current membership, never a new grant.
 if action='get' then
  perform private.admin_invitation_admin(actor,shop);
  return private.admin_invitation_json(i);
 end if;
 if action='respond' then
  if i.recipient_user_id<>actor then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  if jsonb_typeof(d->'decision') is distinct from 'string' or(d->>'decision') not in('accept','reject') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  if i.status='accepted' and d->>'decision'='accept' then
   if m.expired then raise exception using errcode='23505',message='CONFLICT';end if;
   perform 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active';
   if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
   return private.admin_invitation_json(i);
  elsif i.status='rejected' and d->>'decision'='reject' then return private.admin_invitation_json(i);end if;
  if i.status<>'pending' or m.expired or m.expires_at<=clock_timestamp() then raise exception using errcode='23505',message='CONFLICT';end if;
 end if;
 -- MUTATING INVITATION PATH: common shop lock, then invitation lock and rows.
 perform private.authority_lock(shop);
 if action='respond' then
  if i.recipient_user_id<>actor then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 elsif action<>'finish' then perform private.authority_assert(actor,shop,'administrators');
 end if;
 perform pg_advisory_xact_lock(hashtextextended('admin-invitation-shop:'||shop::text,0));
 select * into i from public.staff_invitations where id=target and role='administrator' for update;
 select * into m from private.admin_invitation_mail where invitation_id=target for update;
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 stamp:=clock_timestamp();
 if action='finish' then
  if jsonb_typeof(d->'claimId') is distinct from 'string' or jsonb_typeof(d->'status') is distinct from 'string' or(d->>'status') not in('sent','failed','unknown') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  claim:=(d->>'claimId')::uuid;requested_state:=d->>'status';
  if m.claim_id is distinct from claim or m.claim_actor_id is distinct from actor then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if m.delivery_state<>'sending' then
   if m.delivery_state=requested_state then return jsonb_build_object('ok',true);end if;
   raise exception using errcode='23505',message='CONFLICT';
  end if;
  update private.admin_invitation_mail set delivery_state=requested_state where invitation_id=target;
  return jsonb_build_object('ok',true);
 elsif action='claim' then
  if jsonb_typeof(d->'claimId') is distinct from 'string' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  if i.status<>'pending' or m.expired or m.expires_at<=stamp or m.delivery_state in('sending','sent','unknown') then return jsonb_build_object('claimed',false,'status',m.delivery_state);end if;
  perform 1 from auth.users u where u.id=i.recipient_user_id and lower(u.email)=m.recipient_email
   and u.email_confirmed_at is not null and not u.is_anonymous and(u.banned_until is null or u.banned_until<=stamp) for share;
  if not found then raise exception using errcode='P0001',message='PROFILE_REQUIRED';end if;
  claim:=(d->>'claimId')::uuid;
  update private.admin_invitation_mail set delivery_state='sending',claim_id=claim,claim_actor_id=actor where invitation_id=target;
  return jsonb_build_object('claimed',true,'envelope',jsonb_build_object('invitationId',target,'recipientEmail',m.recipient_email,
    'barbershopName',(select name from public.barbershops where id=shop),'expiresAt',to_char(m.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
 elsif action='cancel' then
  if i.status='cancelled' and not m.expired then return private.admin_invitation_json(i);end if;
  if i.status<>'pending' or m.expired or m.expires_at<=stamp then raise exception using errcode='23505',message='CONFLICT';end if;
  update public.staff_invitations set status='cancelled',responded_at=stamp where id=target returning * into i;
  return private.admin_invitation_json(i);
 end if;
 if jsonb_typeof(d->'decision') is distinct from 'string' or(d->>'decision') not in('accept','reject') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 -- Recheck after waiting: another response may have committed while we waited.
 if i.status='accepted' and d->>'decision'='accept' then
  if m.expired then raise exception using errcode='23505',message='CONFLICT';end if;
  perform 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active';
  if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
  return private.admin_invitation_json(i);
 elsif i.status='rejected' and d->>'decision'='reject' then return private.admin_invitation_json(i);end if;
 if i.status<>'pending' or m.expired or m.expires_at<=stamp then raise exception using errcode='23505',message='CONFLICT';end if;
 if d->>'decision'='reject' then update public.staff_invitations set status='rejected',responded_at=stamp where id=target returning * into i;
 else
  perform private.authority_validate_invitation(i.id);
  perform private.authority_assert_room(shop,actor);
  perform 1 from public.barbershop_memberships bm join auth.users u on u.id=bm.user_id
   where bm.user_id=i.inviter_user_id and bm.barbershop_id=shop and bm.role='administrator' and bm.status='active'
   and u.email_confirmed_at is not null and not u.is_anonymous and(u.banned_until is null or u.banned_until<=stamp) for share of bm,u;
  if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
  select jsonb_build_object('role',role,'status',status) into before_member from public.barbershop_memberships where user_id=actor and barbershop_id=shop;
  insert into public.barbershop_memberships(user_id,barbershop_id,role,status) values(actor,shop,'administrator','active')
   on conflict(user_id,barbershop_id) do update set role='administrator',status='active';
  update public.staff_invitations set status='accepted',responded_at=stamp where id=target returning * into i;
  insert into private.team_authority_events(barbershop_id,actor_user_id,target_user_id,request_id,action,fingerprint,before_state,after_state,result)
  values(shop,actor,actor,i.id,'accepted-administration',jsonb_build_object('invitationId',i.id),coalesce(before_member,'{}'),jsonb_build_object('role','administrator','status','active'),private.admin_invitation_json(i));
 end if;
 return private.admin_invitation_json(i);
exception when unique_violation then raise exception using errcode='23505',message='CONFLICT';
 when invalid_text_representation or datetime_field_overflow then raise exception using errcode='22023',message='INVALID_INPUT';
end;$fn$;

create or replace function private.booking_invitations(actor uuid,shop uuid) returns jsonb language plpgsql stable security definer set search_path='' as $fn$
begin
 if actor is distinct from (select auth.uid()) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 perform private.booking_actor(actor);
 if shop is not null and not exists(select 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active' and private.authority_owner(actor,shop)) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 return coalesce((select jsonb_agg(private.booking_invitation_json(i)||jsonb_build_object('barbershopName',b.name) order by i.created_at,i.id) from public.staff_invitations i join public.barbershops b on b.id=i.barbershop_id where(case when shop is null then i.recipient_user_id=actor else i.barbershop_id=shop end)),'[]');
end;$fn$;

create or replace function private.care_command(actor uuid,d jsonb) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare action text; shop uuid; target uuid; request uuid; r public.reservations;
 c private.booking_care; cfg private.care_settings; old private.care_events; role_name text;
 assigned boolean; key bigint; stamp timestamptz; instructions text; tolerance integer;
begin
 perform private.booking_actor(actor);
 if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'command') is distinct from 'string' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 action:=d->>'command';
 if action in('settings','configure','payment-options') then
  if action='configure' then
   perform private.booking_keys(d,array['command','barbershopId','requestId','noShowToleranceMin','yapeInstructions']);
  else perform private.booking_keys(d,array['command','barbershopId']);end if;
  shop:=(d->>'barbershopId')::uuid;
  if action in('configure','configuration') then perform private.authority_lock(shop);perform private.authority_assert(actor,shop,'operations');end if;
  if shop is null then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  if action='payment-options' then
   if not exists(select 1 from public.barbershop_booking_settings where barbershop_id=shop and publication_state in('published','paused')) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
   return jsonb_build_object('cash',true,'yape',exists(select 1 from private.care_settings where barbershop_id=shop and yape_instructions is not null));
  end if;
  -- Same shop-first lock as operations/booking. No data is created by settings reads.
  if action='configure' then
   perform 1 from public.barbershop_booking_settings where barbershop_id=shop for update;
   perform 1 from public.barbershop_memberships where barbershop_id=shop and user_id=actor and role='administrator' and status='active' for share;
  else
   perform 1 from public.barbershop_memberships where barbershop_id=shop and user_id=actor and role='administrator' and status='active';
  end if;
  if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if action='configure' then
   request:=(d->>'requestId')::uuid;
   if request is null or jsonb_typeof(d->'noShowToleranceMin') is distinct from 'number' or (d->>'noShowToleranceMin') !~ '^\d+$' or jsonb_typeof(d->'yapeInstructions') not in('string','null') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
   tolerance:=(d->>'noShowToleranceMin')::integer;instructions:=nullif(btrim(d->>'yapeInstructions'),'');
   if tolerance<0 or tolerance>1440 or length(instructions)>2000 then raise exception using errcode='22023',message='INVALID_INPUT';end if;
   select * into old from private.care_events where actor_user_id=actor and request_id=request;
   if found and old.fingerprint<>d then raise exception using errcode='23505',message='CONFLICT';end if;
   if not found then
    insert into private.care_settings values(shop,tolerance,instructions) on conflict(barbershop_id) do update set no_show_tolerance_min=excluded.no_show_tolerance_min,yape_instructions=excluded.yape_instructions;
    insert into private.care_events(barbershop_id,actor_user_id,request_id,fingerprint,kind,capacity) values(shop,actor,request,d,'configured','administrator');
   end if;
  end if;
  select * into cfg from private.care_settings where barbershop_id=shop;
  return jsonb_build_object('barbershopId',shop,'noShowToleranceMin',coalesce(cfg.no_show_tolerance_min,10),'yapeInstructions',cfg.yape_instructions);
 end if;
 if action='read' then perform private.booking_keys(d,array['command','reservationId']);
 elsif action in('start','complete','no-show') then perform private.booking_keys(d,array['command','reservationId','requestId']);
 elsif action='receive' then perform private.booking_keys(d,array['command','reservationId','requestId','attested']);
 elsif action='refund' then perform private.booking_keys(d,array['command','reservationId','requestId','attested','reason']);
 else raise exception using errcode='22023',message='INVALID_INPUT';end if;
 target:=(d->>'reservationId')::uuid;
 if target is null then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 select * into r from public.reservations where id=target;
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 if action='read' then
  select m.role into role_name from public.barbershop_memberships m where m.barbershop_id=r.barbershop_id and m.user_id=actor and m.status='active';
  assigned:=coalesce(role_name in('barber','administrator'),false) and exists(select 1 from public.barber_profiles p where p.id=r.barber_id and p.barbershop_id=r.barbershop_id and p.user_id=actor and p.active);
  if actor<>r.client_user_id and not coalesce(role_name='administrator' or assigned,false) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
  return private.care_json(r,actor);
 end if;
 perform private.authority_lock(r.barbershop_id);
 shop:=r.barbershop_id;
 if action='refund' then perform private.authority_assert(actor,shop,'refund');end if;
 perform 1 from public.barbershop_booking_settings where barbershop_id=r.barbershop_id for share;
 for key in select distinct hashtextextended('booking-person:'||x::text,0) k from(select r.client_user_id x union select r.barber_user_id) p order by k loop perform pg_advisory_xact_lock(key);end loop;
 select * into r from public.reservations where id=target for update;
 select m.role into role_name from public.barbershop_memberships m where m.barbershop_id=r.barbershop_id and m.user_id=actor and m.status='active' for share;
 perform 1 from public.barber_profiles p where p.id=r.barber_id and p.barbershop_id=r.barbershop_id and p.user_id=actor and p.active for share;
 assigned:=found and role_name in('barber','administrator');
 if actor<>r.client_user_id and not coalesce(role_name='administrator' or assigned,false) then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 if action in('start','complete','no-show') and not coalesce(assigned,false) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if action='receive' and role_name='administrator' and not assigned then perform private.authority_assert(actor,shop,'operations');end if;
 if action='receive' and not coalesce(role_name='administrator' or assigned,false) then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if action='refund' and role_name is distinct from 'administrator' then raise exception using errcode='42501',message='FORBIDDEN';end if;
 if action in('receive','refund') and d->'attested' is distinct from 'true'::jsonb then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if action='refund' and (jsonb_typeof(d->'reason') is distinct from 'string' or coalesce(length(btrim(d->>'reason')),0)=0 or length(d->>'reason')>2000) then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 request:=(d->>'requestId')::uuid;
 if request is null then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 select * into old from private.care_events where actor_user_id=actor and request_id=request;
 if found then
  if old.fingerprint<>d then raise exception using errcode='23505',message='CONFLICT';end if;
  return private.care_json(r,actor);
 end if;
 select * into c from private.booking_care where reservation_id=target for update;
 -- Legacy bookings have no financial/attendance history and remain unchanged.
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 stamp:=clock_timestamp();
 if action='start' then
  if r.state<>'confirmed' or c.attendance<>'confirmed' or stamp<r.starts_at then raise exception using errcode='23505',message='CONFLICT';end if;
  update private.booking_care set attendance='in-service' where reservation_id=target;
 elsif action='complete' then
  if r.state<>'confirmed' or c.attendance<>'in-service' then raise exception using errcode='23505',message='CONFLICT';end if;
  update private.booking_care set attendance='completed' where reservation_id=target;
 elsif action='no-show' then
  if r.state<>'confirmed' or c.attendance<>'confirmed' or stamp<r.starts_at+make_interval(mins=>c.no_show_tolerance_min) then raise exception using errcode='23505',message='CONFLICT';end if;
  update private.booking_care set attendance='no-show' where reservation_id=target;
 elsif action='receive' then
  if c.payment_status<>'pending' then raise exception using errcode='23505',message='CONFLICT';end if;
  update private.booking_care set payment_status='paid' where reservation_id=target;
 elsif action='refund' then
  if r.state<>'cancelled' or c.payment_status<>'paid' then raise exception using errcode='23505',message='CONFLICT';end if;
  update private.booking_care set payment_status='refunded' where reservation_id=target;
 end if;
 insert into private.care_events(reservation_id,barbershop_id,actor_user_id,request_id,fingerprint,kind,capacity,occurred_at,reason,amount_minor,method)
 values(target,r.barbershop_id,actor,request,d,action,case when action in('start','complete','no-show') then 'barber' else role_name end,stamp,nullif(btrim(d->>'reason'),''),case when action in('receive','refund') then c.amount_minor else null end,case when action in('receive','refund') then c.method else null end);
 return private.care_json(r,actor);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='INVALID_INPUT';
end $fn$;

create or replace function private.care_json(r public.reservations,actor uuid) returns jsonb
language sql stable security definer set search_path='' as $fn$
 select jsonb_build_object(
 'reservationId',r.id,
 'attendance',case when c.reservation_id is null then null when r.state='cancelled' then 'cancelled' else c.attendance end,
 'noShowToleranceMin',c.no_show_tolerance_min,
 'payment',case when c.reservation_id is null then null else jsonb_build_object('method',c.method,'status',c.payment_status,'amountMinor',c.amount_minor,'currency','PEN') end,
 'yapeInstructions',c.yape_instructions_snapshot,
 'events',coalesce((select jsonb_agg(jsonb_build_object('kind',e.kind,'occurredAt',to_char(e.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'actorUserId',e.actor_user_id,'capacity',e.capacity,'reason',e.reason) order by e.occurred_at,e.id) from private.care_events e where e.reservation_id=r.id),'[]'::jsonb),
 'permissions',jsonb_build_object(
 'attend',exists(select 1 from public.barber_profiles p join public.barbershop_memberships m on m.user_id=p.user_id and m.barbershop_id=p.barbershop_id where p.id=r.barber_id and p.user_id=actor and p.active and m.status='active' and m.role in('barber','administrator')),
 'receive',exists(select 1 from public.barbershop_memberships m where m.barbershop_id=r.barbershop_id and m.user_id=actor and m.status='active' and ((m.role='administrator' and exists(select 1 from private.barbershop_ownership where barbershop_id=r.barbershop_id)) or exists(select 1 from public.barber_profiles p where p.id=r.barber_id and p.user_id=actor and p.active))),
 'refund',exists(select 1 from public.barbershop_memberships m where m.barbershop_id=r.barbershop_id and m.user_id=actor and m.status='active' and m.role='administrator' and private.authority_owner(actor,r.barbershop_id))))
 from (select 1) seed left join private.booking_care c on c.reservation_id=r.id;
$fn$;

create or replace function private.guard_admin_invitation_accept() returns trigger
language plpgsql security invoker set search_path='' as $fn$
begin
 perform private.authority_validate_invitation(old.id);
 perform private.authority_assert_room(old.barbershop_id,new.recipient_user_id);
 if not exists(select 1 from private.admin_invitation_mail md where md.invitation_id=old.id and not md.expired and md.expires_at>clock_timestamp())
  or not exists(select 1 from public.barbershop_memberships bm where bm.user_id=new.recipient_user_id and bm.barbershop_id=new.barbershop_id and bm.role='administrator' and bm.status='active')
 then raise exception using errcode='23505',message='CONFLICT';end if;return new;
end;$fn$;

create or replace function private.reschedule_capacity(actor uuid,r public.reservations) returns text
language plpgsql security invoker set search_path='' as $fn$
declare role_name text;
begin
 select m.role into role_name from public.barbershop_memberships m
 where m.user_id=actor and m.barbershop_id=r.barbershop_id and m.status='active' for share;
 if role_name='administrator' and exists(select 1 from private.barbershop_ownership where barbershop_id=r.barbershop_id) then return 'administrator';end if;
 if role_name in('barber','administrator') then
  perform 1 from public.barber_profiles p where p.id=r.barber_id and p.user_id=actor
    and p.barbershop_id=r.barbershop_id and p.active for share;
  if found then return 'barber';end if;
 end if;
 if actor=r.client_user_id then return 'client';end if;
 raise exception using errcode='P0002',message='NOT_AVAILABLE';
end;$fn$;

create or replace function private.reschedule_command(actor uuid,action text,d jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $fn$
declare r public.reservations;cfg public.barbershop_booking_settings;old_event private.reschedule_events;
 target uuid;shop uuid;request uuid;reason text;capacity text;stamp timestamptz;at_time timestamptz;
 expected timestamptz;local_time timestamp;day date;response jsonb;before_start timestamptz;advance integer;
begin
 perform private.booking_actor(actor);
 if action in('get-policy','set-policy') then
  if action='get-policy' then perform private.booking_keys(d,array['barbershopId']);
  else perform private.booking_keys(d,array['barbershopId','advanceMin']);end if;
  if jsonb_typeof(d->'barbershopId') is distinct from 'string' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  shop:=(d->>'barbershopId')::uuid;
  if action='set-policy' then perform private.authority_lock(shop);perform private.authority_assert(actor,shop,'operations');end if;
  if action='set-policy' then perform 1 from public.barbershop_booking_settings where barbershop_id=shop for update;
  else perform 1 from public.barbershop_booking_settings where barbershop_id=shop for share;end if;
  if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
  perform 1 from public.barbershop_memberships where user_id=actor and barbershop_id=shop and role='administrator' and status='active' for share;
  if not found then raise exception using errcode='42501',message='FORBIDDEN';end if;
  if action='set-policy' then
   if jsonb_typeof(d->'advanceMin') is distinct from 'number' or (d->>'advanceMin') !~ '^[0-9]+$' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
   advance:=(d->>'advanceMin')::integer;
   if coalesce((select reschedule_advance_min from private.reschedule_settings where barbershop_id=shop),120) is distinct from advance then
    insert into private.reschedule_settings(barbershop_id,reschedule_advance_min) values(shop,advance)
     on conflict(barbershop_id) do update set reschedule_advance_min=excluded.reschedule_advance_min;
    update public.barbershop_booking_settings set version=version+1 where barbershop_id=shop;
   end if;
  end if;
  return jsonb_build_object('barbershopId',shop,'advanceMin',coalesce((select reschedule_advance_min from private.reschedule_settings where barbershop_id=shop),120));
 end if;
 if action='reschedule' then perform private.booking_keys(d,array['requestId','reservationId','expectedStartsAt','startsAt'],array['reason']);
 elsif action='slots' then perform private.booking_keys(d,array['reservationId','localDate']);
 elsif action='history' then perform private.booking_keys(d,array['reservationId']);
 else raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if jsonb_typeof(d->'reservationId') is distinct from 'string' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 target:=(d->>'reservationId')::uuid;
 r:=private.reschedule_lock(actor,target,action='reschedule');
 capacity:=private.reschedule_capacity(actor,r);
 if action='history' then
  return coalesce((select jsonb_agg(jsonb_build_object('oldStartsAt',to_char(e.old_starts_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'newStartsAt',to_char(e.new_starts_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'capacity',e.capacity,'reason',e.reason,
   'occurredAt',to_char(e.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) order by e.occurred_at,e.id)
   from(select * from private.reschedule_events where reservation_id=r.id order by occurred_at desc,id desc limit 200)e),'[]'::jsonb);
 end if;
 if action='reschedule' then
  if jsonb_typeof(d->'requestId') is distinct from 'string' or jsonb_typeof(d->'startsAt') is distinct from 'string'
   or jsonb_typeof(d->'expectedStartsAt') is distinct from 'string'
   or (d->>'startsAt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
   or (d->>'expectedStartsAt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
   or(d?'reason' and(jsonb_typeof(d->'reason') is distinct from 'string' or length(d->>'reason')>2000))
   then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  request:=(d->>'requestId')::uuid;at_time:=(d->>'startsAt')::timestamptz;expected:=(d->>'expectedStartsAt')::timestamptz;
  reason:=nullif(btrim(d->>'reason'),'');
  if not isfinite(at_time) or not isfinite(expected) or expected=at_time then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  select * into old_event from private.reschedule_events where actor_user_id=actor and request_id=request;
  if found then
   if old_event.fingerprint<>d then raise exception using errcode='23505',message='CONFLICT';end if;
   return jsonb_build_object('detail',old_event.result_json,'replayed',true);
  end if;
  if r.starts_at<>expected then raise exception using errcode='23505',message='CONFLICT';end if;
 end if;
 stamp:=clock_timestamp();perform private.reschedule_eligible(r,capacity,reason,stamp,action='reschedule');
 select * into cfg from public.barbershop_booking_settings where barbershop_id=r.barbershop_id;
 if cfg.publication_state<>'published' then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 if action='slots' then
  if jsonb_typeof(d->'localDate') is distinct from 'string' or (d->>'localDate') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  day:=(d->>'localDate')::date;
  if day<(stamp at time zone 'America/Lima')::date or day>(stamp at time zone 'America/Lima')::date+cfg.booking_horizon_days then return '[]'::jsonb;end if;
  return coalesce((select jsonb_agg(jsonb_build_object('startsAt',to_char(t.at_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'endsAt',to_char((t.at_time+make_interval(mins=>r.duration_min)) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'estimatedTotal',jsonb_build_object('amountMinor',(r.total_amount*100)::bigint,'currency','PEN')) order by t.at_time)
   from(select(day+make_interval(mins=>m)) at time zone 'America/Lima' at_time from generate_series(0,1439,cfg.slot_step_min) m)t
   where t.at_time<>r.starts_at and t.at_time>=stamp+make_interval(mins=>cfg.minimum_notice_min)
   and private.reschedule_available(r,t.at_time)),'[]'::jsonb);
 end if;
 local_time:=at_time at time zone 'America/Lima';
 if at_time<stamp+make_interval(mins=>cfg.minimum_notice_min) or local_time::date>(stamp at time zone 'America/Lima')::date+cfg.booking_horizon_days
   or extract(second from local_time)<>0 or(extract(hour from local_time)*60+extract(minute from local_time))::int%cfg.slot_step_min<>0
   then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 if not private.reschedule_available(r,at_time) then raise exception using errcode='23505',message='Profesional no disponible en ese horario';end if;
 -- Lock assigned active membership/profile until commit, just like confirmation004.
 perform 1 from public.barbershop_memberships where barbershop_id=r.barbershop_id and user_id=r.barber_user_id and status='active' and role in('barber','administrator') for share;
 if not found then raise exception using errcode='23505',message='Profesional no disponible en ese horario';end if;
 perform 1 from public.barber_profiles where id=r.barber_id and barbershop_id=r.barbershop_id and active for share;
 if not found then raise exception using errcode='23505',message='Profesional no disponible en ese horario';end if;
 before_start:=r.starts_at;
 update public.reservations set starts_at=at_time,ends_at=at_time+make_interval(mins=>r.duration_min),
   occupied_until=at_time+make_interval(mins=>r.duration_min+r.buffer_min) where id=r.id returning * into r;
 response:=private.reservation_json(r);
 insert into private.reschedule_events(reservation_id,barbershop_id,old_starts_at,new_starts_at,actor_user_id,capacity,reason,occurred_at,request_id,fingerprint,result_json)
  values(r.id,r.barbershop_id,before_start,at_time,actor,capacity,reason,stamp,request,d,response);
 return jsonb_build_object('detail',response,'replayed',false);
exception
 when exclusion_violation then raise exception using errcode='23505',message='Profesional no disponible en ese horario';
 when unique_violation then raise exception using errcode='23505',message='CONFLICT';
 when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then raise exception using errcode='22023',message='INVALID_INPUT';
end;$fn$;

create or replace function private.reservation_cancel(actor uuid,d jsonb) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare target uuid; request uuid; r public.reservations; person uuid; client uuid; shop uuid; key bigint;
 staff text; reason text; stamp timestamptz; capacity text;
begin
 perform private.booking_actor(actor);
 perform private.booking_keys(d,array['requestId','reservationId'],array['reason']);
 if jsonb_typeof(d->'requestId') is distinct from 'string' or jsonb_typeof(d->'reservationId') is distinct from 'string' or (d ? 'reason' and jsonb_typeof(d->'reason') is distinct from 'string') then raise exception using errcode='22023',message='INVALID_INPUT';end if;
 target:=(d->>'reservationId')::uuid;request:=(d->>'requestId')::uuid;reason:=nullif(btrim(d->>'reason'),'');
 select barber_user_id,client_user_id,barbershop_id into person,client,shop from public.reservations where id=target;
 if not found then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 -- Same protocol as confirmation: shop configuration, sorted physical people, then rows.
 perform 1 from public.barbershop_booking_settings where barbershop_id=shop for share;
 for key in select distinct hashtextextended('booking-person:'||x::text,0) k from (select client x union select person) ids order by k loop perform pg_advisory_xact_lock(key);end loop;
 select * into r from public.reservations where id=target for update;
 select m.role into staff from public.barbershop_memberships m where m.user_id=actor and m.barbershop_id=r.barbershop_id and m.status='active' and (m.role='administrator' or (m.role='barber' and exists(select 1 from public.barber_profiles p where p.id=r.barber_id and p.user_id=actor and p.barbershop_id=r.barbershop_id and p.active))) for share;
 if staff='administrator' and not exists(select 1 from private.barbershop_ownership where barbershop_id=shop) then staff:=case when exists(select 1 from public.barber_profiles p where p.id=r.barber_id and p.user_id=actor and p.active) then 'barber' else null end;end if;
 if actor<>r.client_user_id and staff is null then raise exception using errcode='P0002',message='NOT_AVAILABLE';end if;
 -- An authorized repetition preserves the first event, timestamp, actor and reason.
 if r.state='cancelled' then return private.reservation_json(r);end if;
 stamp:=clock_timestamp();
 if actor=r.client_user_id and private.cancellation_before_limit(r.starts_at,(r.policy_snapshot->>'cancellationAdvanceMin')::integer,stamp) then capacity:='client';
 elsif staff is not null then
  if reason is null then raise exception using errcode='22023',message='INVALID_INPUT';end if;
  capacity:=staff;
 else raise exception using errcode='42501',message='FORBIDDEN';end if;
 update public.reservations set state='cancelled',cancelled_at=stamp where id=target returning * into r;
 insert into public.reservation_events(reservation_id,barbershop_id,actor_user_id,capacity,kind,occurred_at,reason) values(r.id,r.barbershop_id,actor,capacity,'cancelled',stamp,reason);
 return private.reservation_json(r);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='INVALID_INPUT';
end $fn$;

-- Explicit helper closure. No broad schema-wide revoke, preserving earlier contracts.
revoke all on function private.authority_lock(uuid) from public,anon,authenticated,service_role;
revoke all on function private.authority_owner(uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function private.authority_assert(uuid,uuid,text,boolean) from public,anon,authenticated,service_role;
revoke all on function private.authority_assert_room(uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function private.authority_invariant() from public,anon,authenticated,service_role;
revoke all on function private.authority_no_event_changes() from public,anon,authenticated,service_role;
revoke all on function private.authority_capabilities(uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function private.authority_validate_invitation(uuid) from public,anon,authenticated,service_role;
revoke all on function private.regularize_barbershop_ownership(uuid,uuid,jsonb,text) from public,anon,authenticated,service_role;
revoke all on function private.admin_invitation_command(uuid,text,jsonb),private.admin_invitation_admin(uuid,uuid),private.care_command(uuid,jsonb),private.care_json(public.reservations,uuid),private.guard_admin_invitation_accept() from public,anon,authenticated,service_role;
-- booking_command is an existing service-role entry helper, now guarded in its body.
revoke all on function private.booking_command(uuid,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function private.booking_command(uuid,text,jsonb) to service_role;
revoke all on function private.booking_invitations(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function private.booking_invitations(uuid,uuid) to authenticated;
-- Preserve create RPC invoker's minimum bridge, which now atomically records ownership.
revoke all on function private.create_own_barbershop(uuid,text) from public,anon,authenticated,service_role;
grant execute on function private.create_own_barbershop(uuid,text) to service_role;
grant execute on function private.care_command(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;
